//! pi-env daemon: serves the package wire protocol over stdin/stdout.
mod decode;mod errors;mod exec;mod frame;mod fs;mod scan;mod sys;
use errors::Failure;use frame::{CANCEL,Frame,PING,REQUEST,RESULT};use parking_lot::Mutex;use serde_json::{Value,json};use std::{collections::HashMap,env,fs::{File,ReadDir},io::{self,BufReader,BufWriter,Write},sync::{atomic::{AtomicBool,AtomicU64,Ordering},mpsc::{self,Sender},Arc},thread,time::{Duration,SystemTime,UNIX_EPOCH}};
const PROTOCOL:u64=1;const PING_INTERVAL:Duration=Duration::from_secs(5);const SILENCE_LIMIT_MS:u64=30_000;const SCAN_CHUNK:usize=64*1024;
enum Handle{File(Arc<File>,String),Dir(Box<ReadDir>,String)}
enum Cancel{Flag(Arc<AtomicBool>),Exec(Sender<exec::Message>)}
struct Server{out:Sender<Frame>,tmpdir:String,handles:Mutex<HashMap<u64,Handle>>,next_handle:AtomicU64,cancels:Mutex<HashMap<u32,Cancel>>,groups:exec::Groups}
fn now_ms()->u64{SystemTime::now().duration_since(UNIX_EPOCH).map(|d|d.as_millis()as u64).unwrap_or(0)}
fn field<'a>(j:&'a Value,k:&str)->Result<&'a str,Failure>{j[k].as_str().ok_or_else(||Failure::new("EINVAL",format!("missing field {k}")))}
fn number(j:&Value,k:&str)->Result<u64,Failure>{j[k].as_u64().ok_or_else(||Failure::new("EINVAL",format!("missing or invalid field {k}")))}
impl Server{
 fn handle(&self,j:&Value)->Result<Handle,Failure>{let id=number(j,"handle")?;match self.handles.lock().get(&id){Some(Handle::File(f,p))=>Ok(Handle::File(f.clone(),p.clone())),Some(Handle::Dir(..))=>Err(Failure::new("EBADF","not a file handle")),None=>Err(Failure::new("EBADF","unknown handle"))}}
 fn file(&self,j:&Value)->Result<(Arc<File>,String),Failure>{match self.handle(j)?{Handle::File(f,p)=>Ok((f,p)),Handle::Dir(..)=>Err(Failure::new("EBADF","not a file handle"))}}
 fn insert(&self,h:Handle)->u64{let id=self.next_handle.fetch_add(1,Ordering::Relaxed);self.handles.lock().insert(id,h);id}
 fn dispatch(&self,id:u32,j:&Value,payload:Vec<u8>)->Result<(Value,Vec<u8>),Failure>{let op=j["op"].as_str().unwrap_or_default();let plain=|r:Result<Value,Failure>|r.map(|v|(v,Vec::new()));match op{
 "hello"=>plain(Ok(json!({"protocol":PROTOCOL,"version":env!("CARGO_PKG_VERSION"),"os":env::consts::OS,"arch":env::consts::ARCH,"home":sys::home(),"separator":sys::PATH_SEPARATOR,"tmpdir":self.tmpdir,"pid":std::process::id()}))),
 "lstat"=>plain(fs::lstat(field(j,"path")?)),"realpath"=>plain(fs::realpath(field(j,"path")?)),"write"=>plain(fs::write(field(j,"path")?,j["append"].as_bool().unwrap_or(false),&payload)),"truncate"=>plain(fs::truncate(field(j,"path")?,number(j,"size")?)),"fsync"=>plain(fs::fsync(field(j,"path")?)),"rename"=>plain(fs::rename(field(j,"path")?,field(j,"to")?)),"mkdir"=>plain(fs::mkdir(field(j,"path")?,j["recursive"].as_bool().unwrap_or(false))),"rm"=>plain(fs::rm(field(j,"path")?,j["recursive"].as_bool().unwrap_or(false),j["force"].as_bool().unwrap_or(false))),"mkdtemp"=>plain(fs::mkdtemp(field(j,"path")?)),
 "open"=>{let path=field(j,"path")?;let(file,info)=fs::open_reader(path,j["noFollow"].as_bool().unwrap_or(false))?;let h=self.insert(Handle::File(Arc::new(file),path.to_string()));plain(Ok(json!({"handle":h,"info":info})))},
 "pread"=>{let(file,path)=self.file(j)?;let length=(number(j,"length")?as usize).min(frame::MAX_PAYLOAD);Ok((json!({}),fs::pread(&file,&path,number(j,"offset")?,length)?))},
 "fstat"=>{let(file,path)=self.file(j)?;let metadata=file.metadata().map_err(|e|Failure::io(&e,"fstat",&path))?;plain(Ok(fs::info(&path,&metadata)))},"scanLines"=>{let(file,path)=self.file(j)?;plain(self.scan_lines(id,&file,&path,j))},
 "opendir"=>{let path=field(j,"path")?;let dir=std::fs::read_dir(path).map_err(|e|Failure::io(&e,"opendir",path))?;let h=self.insert(Handle::Dir(Box::new(dir),path.to_string()));plain(Ok(json!({"handle":h})))},"readdir"=>plain(self.read_dir(j)),"close"=>{self.handles.lock().remove(&number(j,"handle")?);plain(Ok(json!({})))},
 "exec"=>{let request=exec::ExecRequest::from_json(j)?;let(sender,receiver)=mpsc::channel();self.cancels.lock().insert(id,Cancel::Exec(sender.clone()));plain(exec::run(id,request,&self.tmpdir,&self.out,(sender,receiver),&self.groups))},_=>Err(Failure::new("EINVAL",format!("unknown operation {op}")))}}
 fn scan_lines(&self,id:u32,file:&File,path:&str,j:&Value)->Result<Value,Failure>{let start=number(j,"startLine")?;let end=j["endLine"].as_u64();if end.is_some_and(|e|e<=start){return Err(Failure::new("EINVAL","Invalid line range"))}let cancelled=Arc::new(AtomicBool::new(false));self.cancels.lock().insert(id,Cancel::Flag(cancelled.clone()));let mut scanner=scan::LineScanner::new(start,end);let mut buffer=vec![0;SCAN_CHUNK];let mut position=0u64;loop{if cancelled.load(Ordering::Relaxed){return Err(Failure::new("aborted","aborted"))}let read=sys::read_at(file,&mut buffer,position).map_err(|e|Failure::io(&e,"read",path))?;if read==0{return Ok(scanner.finish())}scanner.push(&buffer[..read]);position+=read as u64}}
 fn read_dir(&self,j:&Value)->Result<Value,Failure>{let id=number(j,"handle")?;let max=number(j,"max")?.max(1)as usize;let mut handles=self.handles.lock();let Some(Handle::Dir(dir,path))=handles.get_mut(&id)else{return Err(Failure::new("EBADF","not a directory handle"))};let mut entries=Vec::new();let mut done=false;while entries.len()<max{match dir.next(){None=>{done=true;break},Some(Err(e))=>return Err(Failure::io(&e,"readdir",path)),Some(Ok(entry))=>{let name=entry.file_name().to_string_lossy().into_owned();let entry_path=entry.path().to_string_lossy().into_owned();entries.push(match std::fs::symlink_metadata(entry.path()){Ok(m)=>json!({"name":name,"info":fs::info(&entry_path,&m)}),Err(e)=>json!({"name":name,"error":Failure::io(&e,"lstat",&entry_path).to_json()})})}}}Ok(json!({"entries":entries,"done":done}))}
}
fn kill_all(groups:&exec::Groups){for pid in groups.lock().iter(){exec::kill_group(*pid)}}
fn serve(token:&str)->io::Result<()>{let stdout=io::stdout();{let mut lock=stdout.lock();writeln!(lock,"PI-ENV {token}")?;lock.flush()?}let(out,frames)=mpsc::channel::<Frame>();thread::spawn(move||{let mut writer=BufWriter::with_capacity(1<<20,io::stdout().lock());for frame in frames{if frame::write_frame(&mut writer,&frame).is_err(){break}}});let server=Arc::new(Server{out:out.clone(),tmpdir:sys::tmpdir(),handles:Mutex::new(HashMap::new()),next_handle:AtomicU64::new(1),cancels:Mutex::new(HashMap::new()),groups:Arc::new(Mutex::new(Default::default()))});let last_seen=Arc::new(AtomicU64::new(now_ms()));{let out=out.clone();let seen=last_seen.clone();let groups=server.groups.clone();thread::spawn(move||loop{thread::sleep(PING_INTERVAL);let _=out.send(Frame::new(PING,0,json!({})));if now_ms().saturating_sub(seen.load(Ordering::Relaxed))>SILENCE_LIMIT_MS{kill_all(&groups);std::process::exit(0)}});}let mut input=BufReader::with_capacity(1<<20,io::stdin().lock());while let Some(request)=frame::read_frame(&mut input)?{last_seen.store(now_ms(),Ordering::Relaxed);match request.kind{REQUEST=>{let server=server.clone();thread::spawn(move||{let id=request.id;let reply=match server.dispatch(id,&request.json,request.payload){Ok((j,p))=>Frame::with_payload(RESULT,id,j,p),Err(e)=>Frame::new(frame::ERROR,id,e.to_json())};server.cancels.lock().remove(&id);let _=server.out.send(reply);});},CANCEL=>match server.cancels.lock().get(&request.id){Some(Cancel::Exec(sender))=>{let _=sender.send(if request.json["mode"].as_str()==Some("kill"){exec::Message::Kill}else{exec::Message::Cancel});},Some(Cancel::Flag(flag))=>flag.store(true,Ordering::Relaxed),None=>{}},_=>{}}}kill_all(&server.groups);Ok(())}
fn main(){let args:Vec<String>=env::args().collect();match args.get(1).map(String::as_str){Some("serve")=>{let token=args.iter().position(|a|a=="--token").and_then(|i|args.get(i+1));let Some(token)=token else{eprintln!("usage: pi-env serve --token <hex>");std::process::exit(2)};if let Err(e)=serve(token){eprintln!("pi-env: {e}");std::process::exit(1)}},Some("--version")=>println!("pi-env {}",env!("CARGO_PKG_VERSION")),_=>{eprintln!("usage: pi-env serve --token <hex>");std::process::exit(2)}}}
